// Glyph coverage rasterized from JetBrains Mono Bold (SIL OFL 1.1).
// Font copyright and license: assets/fonts/licenses/JetBrainsMono-OFL.txt.
import type { FxTextureData } from '../runtimeTypes';
const coverage = '';
const raw = typeof atob === 'function' ? atob(coverage) : '';
const data = new Uint8Array(512 * 192 * 4);
for (let i = 0; i < raw.length; i++) { data[i * 4] = raw.charCodeAt(i); data[i * 4 + 3] = 255; }
export const studyGlyphTexture: FxTextureData = { width: 512, height: 192, data };
export const studyGlyphGLSL = `
uniform sampler2D u_glyphAtlas;
float studyGlyph(vec2 local, float code) {
  float index = clamp(floor(code + 0.5) - 32.0, 0.0, 95.0);
  vec2 cell = vec2(mod(index, 16.0), floor(index / 16.0));
  vec2 inset = clamp(vec2(local.x, 1.0-local.y), vec2(0.5/32.0), vec2(31.5/32.0));
  return texture(u_glyphAtlas, (cell + inset) / vec2(16.0, 6.0)).r;
}
`;
